package config

import (
	"errors"
	"fmt"
	"os"
	"strconv"
	"time"
)

const defaultMaxUploadSize = 10 * 1024 * 1024 // 10MB

type Config struct {
	Port              string
	S3BucketName      string
	AWSRegion         string
	S3PresignEndpoint string
	PresignExpiry     time.Duration
	MaxUploadSize     int64
	S3PathStyle       bool
}

func Load() (*Config, error) {
	cfg := &Config{
		Port:         os.Getenv("PORT"),
		S3BucketName: os.Getenv("S3_BUCKET_NAME"),
		AWSRegion:    os.Getenv("AWS_REGION"),
	}

	cfg.S3PathStyle = os.Getenv("S3_PATH_STYLE") == "true"
	cfg.S3PresignEndpoint = os.Getenv("S3_PRESIGN_ENDPOINT")

	if v := os.Getenv("MAX_UPLOAD_SIZE"); v != "" {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("MAX_UPLOAD_SIZE is invalid: %w", err)
		}
		if n <= 0 {
			return nil, errors.New("MAX_UPLOAD_SIZE must be positive")
		}
		cfg.MaxUploadSize = n
	} else {
		cfg.MaxUploadSize = defaultMaxUploadSize
	}

	if cfg.Port == "" {
		cfg.Port = "8080"
	}

	if v := os.Getenv("PRESIGN_EXPIRY"); v != "" {
		d, err := time.ParseDuration(v)
		if err != nil {
			return nil, fmt.Errorf("PRESIGN_EXPIRY is invalid: %w", err)
		}
		cfg.PresignExpiry = d
	} else {
		cfg.PresignExpiry = 15 * time.Minute
	}

	if cfg.S3BucketName == "" {
		return nil, errors.New("S3_BUCKET_NAME is required")
	}

	if cfg.AWSRegion == "" {
		return nil, errors.New("AWS_REGION is required")
	}

	return cfg, nil
}

package config

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestLoad(t *testing.T) {
	tests := []struct {
		name                string
		env                 map[string]string
		wantErr             string
		wantPort            string
		wantBucket          string
		wantRegion          string
		wantS3PathStyle     bool
		wantPresignEndpoint string
		wantPresignExpiry   time.Duration
		wantMaxUploadSize   int64
	}{
		{
			name:    "missing S3_BUCKET_NAME",
			env:     map[string]string{"AWS_REGION": "us-east-1"},
			wantErr: "S3_BUCKET_NAME is required",
		},
		{
			name:    "missing AWS_REGION",
			env:     map[string]string{"S3_BUCKET_NAME": "my-bucket"},
			wantErr: "AWS_REGION is required",
		},
		{
			name:              "defaults",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1"},
			wantPort:          "8080",
			wantBucket:        "my-bucket",
			wantRegion:        "us-east-1",
			wantPresignExpiry: 15 * time.Minute,
			wantMaxUploadSize: 10 * 1024 * 1024,
		},
		{
			name:              "custom port",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "eu-west-1", "PORT": "9090"},
			wantPort:          "9090",
			wantBucket:        "my-bucket",
			wantRegion:        "eu-west-1",
			wantPresignExpiry: 15 * time.Minute,
			wantMaxUploadSize: 10 * 1024 * 1024,
		},
		{
			name:              "custom presign expiry",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "PRESIGN_EXPIRY": "30m"},
			wantPort:          "8080",
			wantBucket:        "my-bucket",
			wantRegion:        "us-east-1",
			wantPresignExpiry: 30 * time.Minute,
			wantMaxUploadSize: 10 * 1024 * 1024,
		},
		{
			name:    "invalid presign expiry",
			env:     map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "PRESIGN_EXPIRY": "notaduration"},
			wantErr: "PRESIGN_EXPIRY is invalid",
		},
		{
			name:              "S3 path style enabled",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "S3_PATH_STYLE": "true"},
			wantPort:          "8080",
			wantBucket:        "my-bucket",
			wantRegion:        "us-east-1",
			wantS3PathStyle:   true,
			wantPresignExpiry: 15 * time.Minute,
			wantMaxUploadSize: 10 * 1024 * 1024,
		},
		{
			name:              "S3 path style disabled by default",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1"},
			wantPort:          "8080",
			wantBucket:        "my-bucket",
			wantRegion:        "us-east-1",
			wantS3PathStyle:   false,
			wantPresignExpiry: 15 * time.Minute,
			wantMaxUploadSize: 10 * 1024 * 1024,
		},
		{
			name:                "custom presign endpoint",
			env:                 map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "S3_PRESIGN_ENDPOINT": "http://localhost:9000"},
			wantPort:            "8080",
			wantBucket:          "my-bucket",
			wantRegion:          "us-east-1",
			wantPresignEndpoint: "http://localhost:9000",
			wantPresignExpiry:   15 * time.Minute,
			wantMaxUploadSize:   10 * 1024 * 1024,
		},
		{
			name:              "presign endpoint empty by default",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1"},
			wantPort:          "8080",
			wantBucket:        "my-bucket",
			wantRegion:        "us-east-1",
			wantPresignExpiry: 15 * time.Minute,
			wantMaxUploadSize: 10 * 1024 * 1024,
		},
		{
			name:              "custom max upload size",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "MAX_UPLOAD_SIZE": "5242880"},
			wantPort:          "8080",
			wantBucket:        "my-bucket",
			wantRegion:        "us-east-1",
			wantMaxUploadSize: 5242880,
			wantPresignExpiry: 15 * time.Minute,
		},
		{
			name:              "default max upload size",
			env:               map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1"},
			wantPort:          "8080",
			wantBucket:        "my-bucket",
			wantRegion:        "us-east-1",
			wantMaxUploadSize: 10 * 1024 * 1024,
			wantPresignExpiry: 15 * time.Minute,
		},
		{
			name:    "invalid max upload size",
			env:     map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "MAX_UPLOAD_SIZE": "notanumber"},
			wantErr: "MAX_UPLOAD_SIZE is invalid",
		},
		{
			name:    "zero max upload size",
			env:     map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "MAX_UPLOAD_SIZE": "0"},
			wantErr: "MAX_UPLOAD_SIZE must be positive",
		},
		{
			name:    "negative max upload size",
			env:     map[string]string{"S3_BUCKET_NAME": "my-bucket", "AWS_REGION": "us-east-1", "MAX_UPLOAD_SIZE": "-1"},
			wantErr: "MAX_UPLOAD_SIZE must be positive",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Clear and set env vars
			for _, key := range []string{"PORT", "S3_BUCKET_NAME", "AWS_REGION", "PRESIGN_EXPIRY", "S3_PATH_STYLE", "S3_PRESIGN_ENDPOINT", "MAX_UPLOAD_SIZE"} {
				t.Setenv(key, "")
			}
			for k, v := range tt.env {
				t.Setenv(k, v)
			}

			cfg, err := Load()

			if tt.wantErr != "" {
				require.Error(t, err)
				assert.Contains(t, err.Error(), tt.wantErr)
				return
			}

			require.NoError(t, err)
			assert.Equal(t, tt.wantPort, cfg.Port)
			assert.Equal(t, tt.wantBucket, cfg.S3BucketName)
			assert.Equal(t, tt.wantRegion, cfg.AWSRegion)
			assert.Equal(t, tt.wantS3PathStyle, cfg.S3PathStyle)
			assert.Equal(t, tt.wantPresignEndpoint, cfg.S3PresignEndpoint)
			assert.Equal(t, tt.wantPresignExpiry, cfg.PresignExpiry)
			assert.Equal(t, tt.wantMaxUploadSize, cfg.MaxUploadSize)
		})
	}
}

