package evaluator

import (
	"context"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"

	"github.com/anthropics/anthropic-sdk-go"
	"github.com/anthropics/anthropic-sdk-go/option"
)

// jiraPattern matches CUSTX-NNNN and ITSM-NNNN ticket references (case-insensitive).
var jiraPattern = regexp.MustCompile(`(?i)\b(CUSTX|ITSM)-\d+\b`)

// RiskLevel represents the severity of an access request.
type RiskLevel string

const (
	RiskLow    RiskLevel = "low"
	RiskMedium RiskLevel = "medium"
	RiskHigh   RiskLevel = "high"
)

// Assessment is the structured output of a Claude risk evaluation.
type Assessment struct {
	JIRATicket         string    `json:"jira_ticket"`
	HasJIRATicket      bool      `json:"has_jira_ticket"`
	DescriptionQuality string    `json:"description_quality"`
	RiskScore          int       `json:"risk_score"`
	RiskLevel          RiskLevel `json:"risk_level"`
	Reasoning          string    `json:"reasoning"`
}

// Request holds the access request fields that the evaluator needs.
type Request struct {
	ID     string
	User   string
	Roles  []string
	Reason string
}

// Evaluator calls Claude to assign a risk score to a Teleport access request.
type Evaluator struct {
	client anthropic.Client
	model  string
}

func New(apiKey, model string) *Evaluator {
	return &Evaluator{
		client: anthropic.NewClient(option.WithAPIKey(apiKey)),
		model:  model,
	}
}

func (e *Evaluator) Evaluate(ctx context.Context, req Request) (*Assessment, error) {
	tickets := jiraPattern.FindAllString(req.Reason, -1)
	prompt := buildPrompt(req.User, req.Roles, req.Reason, tickets)

	msg, err := e.client.Messages.New(ctx, anthropic.MessageNewParams{
		Model:     e.model,
		MaxTokens: 512,
		System: []anthropic.TextBlockParam{
			{Text: "You are a security risk evaluator for Teleport access requests. Respond only with valid JSON."},
		},
		Messages: []anthropic.MessageParam{
			anthropic.NewUserMessage(anthropic.NewTextBlock(prompt)),
		},
	})
	if err != nil {
		return nil, fmt.Errorf("claude API: %w", err)
	}

	if len(msg.Content) == 0 {
		return nil, fmt.Errorf("empty response from claude")
	}

	text := strings.TrimSpace(msg.Content[0].Text)
	// Strip markdown code fences that Claude sometimes adds.
	if strings.HasPrefix(text, "```") {
		if i := strings.Index(text[3:], "\n"); i >= 0 {
			text = strings.TrimSuffix(strings.TrimSpace(text[3+i+1:]), "```")
		}
	}

	var a Assessment
	if err := json.Unmarshal([]byte(text), &a); err != nil {
		return nil, fmt.Errorf("parsing response: %w (raw: %s)", err, text)
	}

	return &a, nil
}

func buildPrompt(user string, roles []string, reason string, tickets []string) string {
	ticketInfo := "none"
	if len(tickets) > 0 {
		ticketInfo = strings.Join(tickets, ", ")
	}

	return fmt.Sprintf(`You are a security risk evaluator for Teleport access requests. Respond ONLY with a valid JSON object — no explanation, no markdown.

Access request details:
  User:            %s
  Requested roles: %s
  Reason provided: %q
  JIRA tickets:    %s

Risk scoring rules:
  1–3  (low)    — valid JIRA ticket (CUSTX-NNN or ITSM-NNN) AND a clear description with business justification
  4–6  (medium) — either a valid JIRA ticket OR a clear description, but not both
  7–10 (high)   — no JIRA ticket AND no/vague description (single words or generic phrases like "need access" score 9–10)

Return exactly this JSON shape:
{
  "jira_ticket":          "<ticket ID or null>",
  "has_jira_ticket":      <true|false>,
  "description_quality":  "<none|poor|fair|good|excellent>",
  "risk_score":           <integer 1–10>,
  "risk_level":           "<low|medium|high>",
  "reasoning":            "<one concise sentence>"
}`,
		user,
		strings.Join(roles, ", "),
		reason,
		ticketInfo,
	)
}

